import pandas as pd
import json
import os
import math

def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        import yaml
        if isinstance(json_data, str):
            data = yaml.load(json_data, Loader=yaml.Loader)
        else:
            data = json_data
    except Exception:
        raise ValueError("Malformed JSON data.")

    if not data or not isinstance(data, list):
        raise ValueError("Empty or invalid JSON data.")

    processed_data = []
    for entry in data:
        if not isinstance(entry, dict) or "Country" not in entry or "Population" not in entry:
            raise ValueError("Invalid entry structure.")

        country = entry["Country"]
        population = entry["Population"]

        if not isinstance(country, str):
            raise ValueError("Country names must be strings.")

        if not isinstance(population, (int, float)) or population < 0:
            raise ValueError("Population must be a non-negative number.")

        processed_data.append({
            "Country": country,
            "Population": math.floor(population)
        })

    df = pd.DataFrame(processed_data, columns=["Country", "Population"])

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except Exception:
        raise IOError(f"Could not write to file {file_path}")

    return os.path.abspath(file_path), df
